// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        // 1. Restrict: caller must not be the current owner (already set in setUp, which is address(this) by default since we deployed it).
        // The setUp function makes msg.sender = address(this) when deploying C, so owner = address(this).
        // We need caller != address(this) to test the non-owner transfer case.
        vm.assume(caller != address(this));

        // 2. Execute the transfer from fuzzed caller.
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // 3. Assert: The owner should remain the original deployer (address(this)) because an unauthorized caller cannot change it.
        // The reference version satisfies this for ALL inputs; the mutant changes owner to newOwner for SOME input (when caller != owner).
        assertTrue(c.owner() == address(this));
    }
}

