pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Make the test contract the initial owner so it can call transferOwnership.
        // The constructor of C does not set owner, so we store this contract as owner via a cheat.
        // Actually, the contract has no constructor, but owner defaults to address(0).
        // To satisfy onlyOwner, we need msg.sender == owner, so we set owner first.
        // Since there is no public setter except transferOwnership (which is guarded), we use vm.store.
        // But that cheatcode is FORBIDDEN.  We need a different approach.
        // The only way to make the test contract the owner without forbidden cheatcodes is to deploy
        // C from an EOA that is the test contract? No, the test contract is a contract.
        // Actually, c.owner() is address(0) initially.  onlyOwner requires msg.sender == owner.
        // So any call from an EOA with address(0) would pass?  No, address(0) is not an EOA.
        // Solidity address(0) is the zero address, and no EOA can have that address.
        // Thus transferOwnership can NEVER be called legitimately in the reference?  That is wrong.
        // Let's re-read the contract.  It has function owned() public onlyOwner {}
        // and modifier onlyOwner { require(msg.sender == owner); _; }
        // But there is no constructor or setter to initialize owner to a non-zero value!
        // Therefore owner is always address(0), and onlyOwner requires msg.sender == address(0).
        // This is a weird contract, but the fuzz test must still work with the given reference.
        // We can vm.prank(address(0)) to call transferOwnership?  No, prank with address(0) might work.
        // In Foundry, vm.prank(0x0) sets msg.sender to 0x0.  Then require(msg.sender == owner) passes.
        // So we can prank from address(0) to call transferOwnership.
        // But the fuzz parameter is the caller or newOwner?  The property is about the resulting owner.
        // We need to fuzz the newOwner address, and the caller must be the current owner (address(0)).
        // So we prank from address(0) and call transferOwnership with newOwner as fuzz parameter.
        // However, the rule is: after a call from the owner, owner must be the caller.
        // But the bug sets owner to address(0).  After the call, owner == address(0) in both?
        // Wait: if we prank from address(0), msg.sender == address(0).  The reference sets owner = newOwner.
        // The bug sets owner = address(0).  So reference owner becomes newOwner, bug owner becomes address(0).
        // The property: owner() must equal msg.sender after the call?  That would be true for reference only if newOwner == address(0).  But newOwner is fuzzed, so reference would break that rule for most inputs.
        // That was the already tried approach (owner must equal argument).
        // The previously tried approach: "After a call to transferOwnership, the owner state variable must equal the address passed as an argument".
        // The description says: "Your rule is too strong for the reference, or your domain admits inputs the reference legitimately handles differently"
        // So we need a different property that holds for reference for ALL admissible inputs and breaks for bug for some.
        // The reference sets owner = newOwner.  The bug sets owner = address(0).
        // So the difference is that in the reference, the new owner is whatever was passed; in the bug, it's forced to 0.
        // A property: "After a successful transferOwnership call, the owner must NOT be address(0) if the argument is not address(0)"?
        // That would hold for reference (if newOwner != 0, owner == newOwner != 0), but bug makes it 0.
        // But the reference could also set owner to 0 if newOwner is 0. So we need to handle that case.
        // The fuzzer can supply newOwner as parameter.  We assume newOwner != address(0) to avoid the trivial case where both satisfy the property.
        // Then assert that owner != address(0).  For reference it's true, for bug it's false.
        // But we must ensure that the call does not revert.  We prank from address(0) so onlyOwner passes.
        // So we need to prank from address(0), which is allowed.
        // The property: if we call transferOwnership with a non-zero address, and the call does not revert, then owner must be non-zero.
        // That's a general rule: the reference never makes owner zero if the argument is non-zero; the bug always makes it zero.
        // We can implement this.
    }

    function testFuzz_property(address newOwner) public {
        // We want to avoid newOwner being address(0) because then both versions would have owner == 0.
        vm.assume(newOwner != address(0));

        // The only way to pass onlyOwner is to be the owner.  The owner is address(0) initially.
        // So we prank as address(0).
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // After the call, the reference has owner == newOwner (non-zero), bug has owner == 0.
        // So assert that owner is not zero.
        assertTrue(c.owner() != address(0));
    }
}

