import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address originalOwner) public {
        vm.assume(originalOwner != address(0));
        vm.assume(originalOwner != caller);
        vm.prank(originalOwner);
        c.transferOwnership(originalOwner);
        assertEq(c.owner(), originalOwner);

        vm.prank(caller);
        try c.owned() {
            fail(); // owned() should revert for a non-owner caller
        } catch {
            // expected: call from a non-owner must revert and owner stays originalOwner
            assertEq(c.owner(), originalOwner);
            return;
        }
        // if owned() did not revert, owner must not change (reference rule); mutant sets it to caller
        assertEq(c.owner(), originalOwner);
    }
}

